import numpy as np
from scipy import ndimage
d = np.load('source_pixels.npz')['rgb']
def reddish(f):
    r,g,b=f[...,0].astype(int),f[...,1].astype(int),f[...,2].astype(int)
    return (r>150)&(r-g>60)&(r-b>60)
# track red tip in region x125-155 y60-75 across frames
for t in range(0,96,2):
    m=reddish(d[t])[60:76,125:156]
    ys,xs=np.nonzero(m)
    if len(xs):
        print(t,'redtip n',len(xs),'cen',round(xs.mean()+125,1),round(ys.mean()+60,1),'x',xs.min()+125,xs.max()+125)
    else:
        print(t,'no red tip')
